// Package schedule installs, verifies and removes the tool's own sync
// schedule: a launchd user agent on macOS, a systemd user timer on Linux.
// `yadm init` and `yadm adopt` install it unless given --no-schedule;
// `yadm check` verifies it is loaded and when it last ran.
//
// The schedule runs `yadm sync --auto` every Interval and once at login or
// wake. A run missed during sleep is not queued again: the next run catches
// up once. The unit files are generated by the tool, not managed through the
// manifest, and name no user path except the binary and $HOME.
//
// Exported API:
//
//	type Scheduler interface{ Install(ctx, Spec) error; Uninstall(ctx) error; Status(ctx) (Status, error) }
//	type Spec struct{ Binary string; Interval time.Duration; Label string }
//	type Status struct{ Installed, Loaded bool; LastRun time.Time; UnitPath string }
//	func ForOS(goos string) (Scheduler, error)
package schedule

import (
	"context"
	"time"

	"github.com/noahkiss/yadm/internal/model"
)

// DefaultInterval is the sync period.
const DefaultInterval = 5 * time.Minute

// DefaultLabel names the launchd agent and the systemd units.
const DefaultLabel = "yadm-sync"

// Spec describes the schedule to install.
type Spec struct {
	Binary   string
	Interval time.Duration
	Label    string
}

// Status is what Status reports.
type Status struct {
	Installed bool      `json:"installed"`
	Loaded    bool      `json:"loaded"`
	LastRun   time.Time `json:"last_run,omitempty"`
	UnitPath  string    `json:"unit_path,omitempty"`
}

// Scheduler manages the platform's user-level scheduler.
type Scheduler interface {
	Install(ctx context.Context, s Spec) error
	Uninstall(ctx context.Context) error
	Status(ctx context.Context) (Status, error)
}

// ForOS returns the scheduler for "darwin" (launchd) or "linux" (systemd).
func ForOS(goos string) (Scheduler, error) { return nil, model.ErrNotImplemented }
